import { useRef, PointerEvent, FC, ComponentType } from 'react';

type Props = {
  onDoublePointerDown?: (e: PointerEvent) => void;
};

export function withDoublePointerDown<P extends object>(
  WrappedComponent: ComponentType<P>
): FC<P & Props> {
  function ComponentWithDoublePointerDown({ onDoublePointerDown, ...props }: P & Props) {
    const lastClickRef = useRef<number | null>(null);

    const handlePointerDown = (e: PointerEvent) => {
      const now = Date.now();
      if (lastClickRef.current && now - lastClickRef.current < 300) {
        onDoublePointerDown?.(e);
        lastClickRef.current = null; // 리셋
      } else {
        lastClickRef.current = now;
      }
    };

    return (
      <WrappedComponent
        {...(props as P)}
        onPointerDown={handlePointerDown}
      />
    );
  }

  const name = WrappedComponent.displayName || WrappedComponent.name || 'Component';
  ComponentWithDoublePointerDown.displayName = `withDoublePointerDown(${name})`;

  return ComponentWithDoublePointerDown;
}

