import {
  MutationFunction,
  UseInfiniteQueryOptions,
  UseMutationOptions,
  UseQueryOptions,
} from '@tanstack/react-query'

export const queryOption = <T extends unknown[], J>(
  key: string[],
  fn: (...payload: T) => Promise<J>
) => {
  return (...payload: T) =>
    ({
      queryKey: [...key, ...payload],
      queryFn: () => fn(...payload),
      staleTime: Infinity,
      refetchOnWindowFocus: false,
    }) satisfies UseQueryOptions<J>
}

export const mutationOption = <T, K>(key: string[], fn: MutationFunction<T, K>) => {
  return () =>
    ({
      mutationKey: key,
      mutationFn: fn,
      retry: 3,
    }) satisfies UseMutationOptions<T, unknown, K>
}

export const infiniteQueryOption = <TParam extends unknown[], TResult>(
  key: string[],
  fn: (...args: TParam) => Promise<TResult>
) => {
  return (...args: TParam) =>
    ({
      queryKey: [...key, ...args],
      queryFn: ({ pageParam }) => {
        if (!pageParam) return fn(...args)

        args.map((arg, index) => {
          if (typeof arg === 'object' && arg !== null) {
            args[index] = { ...arg, ...pageParam } as TParam[number]
          }
        })

        return fn(...args)
      },
      getNextPageParam: (lastPage) => lastPage,
      initialPageParam: undefined,
      staleTime: Infinity,
      refetchOnWindowFocus: false,
    }) satisfies UseInfiniteQueryOptions<TResult, unknown, TResult>
}

