import React, { useState } from 'react'

interface LazyPopupProps {
  open: boolean
  lazy?: boolean
  children: React.ReactNode
}

export const LazyPopup = ({ open, lazy = false, children }: LazyPopupProps) => {
  const [loaded, setLoaded] = useState(!lazy)

  const handleCapture = (e: React.SyntheticEvent) => {
    if (!lazy || loaded) return
    if ((e.target as HTMLElement).tagName === 'IMG') {
      setLoaded(true)
    }
  }

  const visible = open && (!lazy || loaded)

  return visible ? (
    <div className="popup" onLoadCapture={handleCapture}>
      {children}
    </div>
  ) : null
}

import { ConfirmContext } from './ConfirmContext';
import { Dialog } from './Dialog';          // ✨ 자신이 쓰는 Dialog 컴포넌트로 변경
import {
  ReactNode,
  useCallback,
  useMemo,
  useRef,
  useState,
} from 'react';

interface ConfirmProviderProps {
  children: ReactNode;
  defaultSlot?: ReactNode;
  confirmText?: string;
  cancelText?: string;
}

export function ConfirmProvider({
  children,
  defaultSlot,
  confirmText = '확인',
  cancelText = '취소',
}: ConfirmProviderProps) {
  /** 모달 노출 여부 */
  const [open, setOpen] = useState(false);

  /** 모달 본문(슬롯) */
  const [slot, setSlot] = useState<ReactNode>(defaultSlot);

  /** “나중에 실행할” 콜백 & 인자 저장소 */
  const storedCallback = useRef<((...args: unknown[]) => unknown) | null>(null);
  const storedArgs = useRef<unknown[]>([]);

  /* ---------- 핸들러 ---------- */
  const close = useCallback(() => setOpen(false), []);

  const apply = useCallback(() => {
    storedCallback.current?.(...storedArgs.current);
    close();
  }, [close]);

  /** openConfirm: 콜백 + 슬롯 → 래핑된 함수 반환 */
  const openConfirm = useCallback(
    <T extends unknown[]>(
      fn: (...args: T) => unknown,
      customSlot?: ReactNode,
    ) => {
      return (...args: T) => {
        if (customSlot !== undefined) setSlot(customSlot);
        storedCallback.current = (...inner) => fn(...(inner as T));
        storedArgs.current = args;
        setOpen(true);
      };
    },
    [],
  );

  /** Context 값은 메모이제이션으로 안정화 */
  const contextValue = useMemo(() => ({ openConfirm }), [openConfirm]);

  return (
    <ConfirmContext.Provider value={contextValue}>
      {children}

      {/* 실제 다이얼로그 */}
      <Dialog open={open} onClose={close}>
        <Dialog.Content>{slot}</Dialog.Content>
        <Dialog.Footer
          handleApply={apply}
          handleClose={close}
          confirmText={confirmText}
          cancelText={cancelText}
        />
      </Dialog>
    </ConfirmContext.Provider>
  );
}

export function createEasterEgg(
  targetElement: HTMLElement,
  callback: () => void,
  keySequence: string[]
): void {
  let currentSequence: string[] = [];

  // 1. 키 시퀀스를 Base64로 인코딩하여 유추하기 어렵게 만듭니다.
  const obfuscatedSequence = btoa(JSON.stringify(keySequence));

  // 2. 디버거 탐지 함수
  const checkDebugger = () => {
    const threshold = 170; // 개발자 도구 창 크기 임계값
    if (
      window.outerWidth - window.innerWidth > threshold ||
      window.outerHeight - window.innerHeight > threshold
    ) {
      // 디버거가 열려있으면 시퀀스를 초기화하고 동작을 멈춥니다.
      currentSequence = [];
      return true;
    }
    return false;
  };

  // 오해를 유도하는 콘솔 메시지
  (function () {
    try {
      const re = /./;
      re.toString = function () {
        console.log(
          "%cHehe, you found me! But can you figure out the secret code?",
          "color: #9A2EFE; font-size: 14px; font-weight: bold;"
        );
        return " ";
      };
      console.log("%c ", re);
    } catch (e) {}
  })();

  targetElement.addEventListener("keydown", (event: KeyboardEvent) => {
    // 매 키 입력마다 디버거를 확인합니다.
    if (checkDebugger()) {
      return;
    }

    const decodedSequence: string[] = JSON.parse(atob(obfuscatedSequence));
    const requiredKey = decodedSequence[currentSequence.length];

    if (event.key === requiredKey) {
      currentSequence.push(event.key);

      if (currentSequence.length === decodedSequence.length) {
        // 3. 콜백을 비동기적으로 실행하여 직접적인 호출 스택 추적을 어렵게 합니다.
        setTimeout(() => {
          callback();
        }, 0);
        currentSequence = [];
      }
    } else {
      // 순서가 틀리면 처음부터 다시 시작
      // 사용자가 실수로 다른 키를 눌렀을 때를 대비해, 현재 입력이 시퀀스의 첫 키와 같다면 유지합니다.
      if (event.key === decodedSequence[0]) {
        currentSequence = [event.key];
      } else {
        currentSequence = [];
      }
    }
  });
}

